// Import the Component decorator here
import { Component } from '@angular/core';

// Create the StatusCard component class here
@Component({
  selector: 'app-status-card',
  template: `
    <div class="status-card" [ngClass]="getStatusClasses()" /* Add click event here */>
      <span class="status-icon">{{ icon }}</span>
      <span class="status-text">{{ status | titlecase }}</span>
    </div>
  `,
  styles: [`
    .status-card {
      padding: 16px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      gap: 8px;
      cursor: pointer;
      transition: all 0.3s ease;
    }
    .status-card.success {
      background-color: #d4edda;
      border: 1px solid #c3e6cb;
      color: #155724;
    }
    .status-card.warning {
      background-color: #fff3cd;
      border: 1px solid #ffeaa7;
      color: #856404;
    }
    .status-card.error {
      background-color: #f8d7da;
      border: 1px solid #f5c6cb;
      color: #721c24;
    }
    .status-icon {
      font-size: 18px;
      font-weight: bold;
    }
    .status-text {
      font-weight: 500;
    }
  `]
})
export class StatusCard {
  status = 'active';
  type = 'success';
  icon = '✓';

  updateStatus(newStatus, newType) {
    this.status = newStatus;
    this.type = newType;
    if (newType === 'success') this.icon = '✓';
    else if (newType === 'warning') this.icon = '⏳';
    else if (newType === 'error') this.icon = '✗';
    else this.icon = '•';
  }

  getStatusClasses() {
    return {
      [this.type]: true
    };
  }
}
